INSERT INTO nft_source_remediation_0064 (slug, profile, sources)
VALUES ('bored-ape-yacht-club', '{"citation_schema":"field-v1","evidence_policy":{"schema":"forensic-freshness-v1","status_basis":"direct_current","status_as_of":"2026-07-27","last_verified_at":"2026-07-29","next_review_at":"2026-10-29","stale":false},"launched":"BAYC’s current official history states that 10,000 Bored Apes were released on 2021-04-23. The prior presale/sellout sequence is withheld because its cited path now redirects to a generic homepage.","supply":"10,000 Bored Ape NFTs. Companion collections, ApeCoin, ApeChain assets, Otherside assets, and merchandise are outside that count.","mint_price":"Withheld: the accessible current first-party pages reviewed in this remediation do not state the original mint price or audited aggregate proceeds.","community_history":"Yuga describes BAYC as a 10,000-item membership club that expanded through companion collections and recurring community activations. Current official ApeFest and activation pages establish continued programming, not holder retention or financial performance.","founder_engagement":"Yuga’s current About page describes BAYC as beginning with four friends but does not name the full founding or original art team. Individual identities, duties, and continued involvement are therefore withheld in this dossier.","benefits":"BAYC ownership functions as membership and the current license documents holder rights in the associated art; events and other benefits are program-specific and can change. Ownership is not represented as equity or guaranteed yield.","business":"The model joins NFT membership and holder IP with events, merchandise, collaborations, games and Yuga''s broader ecosystem. BAYC token rights, ApeCoin, ApeChain and Yuga corporate economics are separate and are not consolidated here.","analysis":"Thriving is limited to current club operation: the official ApeFest 2026 page was live on 2026-07-27 after a fifth ApeFest in 2025 and the official activation archive showed continuing programs. It does not establish floor, volume, holder retention, royalty revenue, event profitability, ApeCoin performance or Yuga finances.","team":{"founders":"four friends per Yuga; individual roster withheld from the accessible current first-party evidence","current_operator":"Yuga Labs / BAYC","source_ids":["bayc-yuga-about"]},"chronology":[{"date":"2021-04-23","event":"The current official BAYC history states that 10,000 Bored Apes were released.","source_ids":["bayc-founding-current"]},{"date":"2025-10","event":"BAYC held its fifth ApeFest in Las Vegas.","source_ids":["bayc-apefest-2025"]},{"date":"2026-07-27","event":"Official ApeFest 2026 page advertised ticketing to open for an October 17 event.","source_ids":["bayc-apefest-2026"]}],"market_holder_boundaries":{"market":"No current floor, volume, liquidity, royalty receipts, or realized returns.","holders":"No current unique-owner, concentration, retention, or event-conversion rate.","available_evidence":"Official event and activation pages prove operating programs, not secondary-market health.","source_ids":["bayc-apefest-2026","bayc-activations"]},"products_and_value_capture":{"products":["token-gated club","ApeFest","merchandise","holder IP and collaborations","games and broader Yuga integrations"],"capture":"Possible channels include primary/secondary NFT economics, merchandise, events and licensing, but no collection-specific current revenue is asserted.","source_ids":["bayc-license-current","bayc-activations","bayc-yuga-about"]},"why":{"finding":"The strategic combination of recognizable PFP identity, explicit club access, holder use, recurring physical events and ecosystem extensions plausibly explains operational durability; the evidence does not isolate which component caused financial success.","source_ids":["bayc-founding-current","bayc-apefest-2025","bayc-yuga-about"]},"strategic_choices":[{"choice":"Release a fixed 10,000-item collection and frame each NFT as membership rather than art alone.","source_ids":["bayc-founding-current","bayc-yuga-about"]},{"choice":"Extend membership through claims, merchandise, games and in-person events.","source_ids":["bayc-license-current","bayc-yuga-about","bayc-activations"]},{"choice":"Build a broader Yuga ecosystem while retaining BAYC as a distinct collection and club identity.","source_ids":["bayc-yuga-about","bayc-activations"]}],"counterfactual":{"finding":"Without repeated member programming and usable IP/identity surfaces, BAYC could remain recognizable while its club proposition decayed. This analytical scenario is not a claim that current members are retained or satisfied.","source_ids":["bayc-founding-current","bayc-apefest-2026"]},"risks":[{"risk":"Benefits depend on continued Yuga execution and program terms.","source_ids":["bayc-apefest-2026","bayc-activations"]},{"risk":"Collection, company, token, chain and metaverse economics can be incorrectly conflated.","source_ids":["bayc-yuga-about"]},{"risk":"Current event operation does not demonstrate a liquid or appreciating NFT market.","source_ids":["bayc-apefest-2026"]}],"unknowns":["Current holder count, concentration, and active membership rate.","Current floor, volume, royalties, event economics, and BAYC-attributable Yuga revenue.","Individual founder duties, continued involvement, original mint price, and audited aggregate primary proceeds."],"review":{"last_verified_at":"2026-07-29","next_review_at":"2026-10-29","triggers":["ApeFest cancellation or completion","license or benefit changes","stewardship transfer","collection-specific financial disclosure"]},"evidence":[{"field":"launch","value":"10,000 Bored Apes released 2021-04-23; prior presale/sellout sequence withheld","as_of":"2021-04-23","basis":"operator","source_ids":["bayc-founding-current"]},{"field":"supply_or_mint","value":"10,000 Bored Apes; companion assets excluded","as_of":"2021-04-23","basis":"operator","source_ids":["bayc-founding-current","bayc-yuga-about"]},{"field":"mint_price","value":"Withheld — accessible current first-party evidence reviewed here does not state the original mint price","as_of":"2026-07-29","basis":"operator","source_ids":["bayc-founding-current","bayc-yuga-about"]},{"field":"lifecycle_status","value":"thriving — current event and activation operation only, not market performance","as_of":"2026-07-27","basis":"analyst","source_ids":["bayc-apefest-2026","bayc-activations"]},{"field":"community_history","value":"Membership framing, companion collections, and current recurring activations documented; retention withheld","as_of":"2026-07-27","basis":"operator","source_ids":["bayc-yuga-about","bayc-apefest-2025","bayc-apefest-2026","bayc-activations"]},{"field":"founder_engagement","value":"Four-friend origin documented; individual founder roster, duties, and current engagement withheld","as_of":"2026-07-29","basis":"operator","source_ids":["bayc-yuga-about"]},{"field":"benefits","value":"Membership, current holder art rights, events, experiences, and merchandise; terms can change and no yield is promised","as_of":"2026-07-27","basis":"operator","source_ids":["bayc-license-current","bayc-yuga-about","bayc-apefest-2026"]},{"field":"business","value":"Membership and IP extended through events, merchandise, collaborations and broader Yuga products; current economics withheld","as_of":"2026-07-27","basis":"operator","source_ids":["bayc-activations","bayc-yuga-about"]},{"field":"analysis","value":"Current operating continuity is verified; market, holder and financial conclusions are withheld","as_of":"2026-07-27","basis":"analyst","source_ids":["bayc-apefest-2026","bayc-apefest-2025"]}],"forensic_analysis":{"version":"forensic-analysis-v1","outcome":{"label":"thriving","summary":"Bored Ape Yacht Club is thriving as a currently operated membership and IP brand: a 2026 ApeFest surface and continuing activation archive show recurring holder programming. The scope excludes floor performance, holder returns, ApeCoin or ApeChain performance, event profitability, and consolidated Yuga Labs finances.","confidence":"high","as_of":"2026-07-27","source_refs":["bayc-apefest-2026","bayc-activations"]},"why":{"summary":"BAYC turned a fixed avatar collection into a social membership identity, then repeatedly refreshed that identity through holder IP, events, merchandise, and a broader Yuga product network. The observed evidence proves current activation rather than only token persistence. The inference is that repeated offline and online coordination reinforces community distribution; the reviewed sources do not isolate how much each program contributes to retention, revenue, or price.","confidence":"medium","source_refs":["bayc-founding-current","bayc-license-current","bayc-yuga-about","bayc-apefest-2025","bayc-apefest-2026","bayc-activations"]},"strategic_choices":[{"confidence":"high","decision":"Launch a fixed 10,000-avatar membership collection.","consequence":"A legible cohort and shared visual identity made community coordination easier, while concentrating access in a scarce asset whose market price can exclude later users.","source_refs":["bayc-founding-current","bayc-yuga-about"]},{"confidence":"high","decision":"Give holders commercial-use opportunities and treat the NFT as a club membership layer.","consequence":"Community members can extend the brand and identity, but rights and benefits remain program-specific rather than equity or guaranteed cash flow.","source_refs":["bayc-license-current","bayc-yuga-about"]},{"confidence":"high","decision":"Invest in recurring ApeFest events and activation programming.","consequence":"Physical gatherings create repeated social utility beyond marketplace trading; attendance, cost, and retention impact are not disclosed.","source_refs":["bayc-apefest-2025","bayc-apefest-2026","bayc-activations"]},{"confidence":"medium","decision":"Expand BAYC into a broader Yuga ecosystem while keeping token and corporate economics distinct.","consequence":"Cross-product distribution can deepen the franchise, but complexity makes it difficult to attribute value or risk specifically to BAYC holders.","source_refs":["bayc-yuga-about","bayc-activations"]}],"counterfactual":{"summary":"Keeping BAYC as static profile-picture art would have reduced execution cost and ecosystem complexity, but also removed the recurring membership experiences that distinguish an active club from an inert collection. A single tightly controlled brand could preserve consistency while sacrificing holder-led distribution and experimentation.","confidence":"medium","source_refs":["bayc-founding-current","bayc-yuga-about","bayc-activations"]},"watch":[{"signal":"Delivery, attendance, and recurrence of ApeFest and other holder activations.","implication":"Sustained programs support operating continuity; cancellations or shrinking scope would weaken the membership thesis.","source_refs":["bayc-apefest-2026","bayc-activations"]},{"signal":"Changes to holder IP rights and collection-specific benefits.","implication":"Broader usable rights could strengthen distribution, while restrictions or benefit withdrawal could reduce member utility.","source_refs":["bayc-license-current","bayc-yuga-about"]},{"signal":"Separation or consolidation among BAYC, ApeCoin, ApeChain, and other Yuga products.","implication":"Clearer boundaries improve attribution; forced coupling could add token and execution risk to the collection.","source_refs":["bayc-yuga-about"]}],"unknowns":["What are current unique-holder retention, concentration, and active membership rates?","What do ApeFest and other activations cost and how do they affect revenue or retention?","How much value is created by holder commercial use versus Yuga-operated products?","What collection-specific royalty, merchandise, licensing, and operating economics exist?"],"review":{"status":"current","last_reviewed_at":"2026-07-29","next_review_at":"2026-10-29","reviewer":"chaindump-research-desk"}}}', '[{"id":"bayc-origin","title":"\"Let''s Make A NFT\"","url":"https://news.yuga.com/lets-make-a-nft","publisher":"Yuga Labs","source_date":"2022-03-01","source_date_kind":"published","last_verified_at":"2026-07-29","evidence_scope":"historical_event","stale_after":null,"stale":false,"access_state":"unverified","access_checked_at":"2026-07-29","access_http_status":200,"access_final_url":"https://yuga.com/","access_note":"redirected to homepage; cited path not verified"},{"id":"bayc-yuga-about","title":"About Yuga Labs","url":"https://yuga.com/about/","publisher":"Yuga Labs","source_date":null,"source_date_kind":"unknown","last_verified_at":"2026-07-29","evidence_scope":"mechanism","stale_after":null,"stale":false,"access_state":"accessible","access_checked_at":"2026-07-29","access_http_status":200,"access_final_url":"https://yuga.com/about/","access_note":"HTTP 200; content reachable (claim support not re-verified)"},{"id":"bayc-apefest-2025","title":"ApeFest 2025: Las Vegas","url":"https://boredapeyachtclub.com/activations/apefest-2025-las-vegas","publisher":"Bored Ape Yacht Club","source_date":"2025-10-31","source_date_kind":"event","last_verified_at":"2026-07-29","evidence_scope":"historical_event","stale_after":null,"stale":false,"access_state":"accessible","access_checked_at":"2026-07-29","access_http_status":200,"access_final_url":"https://boredapeyachtclub.com/activations/apefest-2025-las-vegas","access_note":"HTTP 200; content reachable (claim support not re-verified)"},{"id":"bayc-apefest-2026","title":"ApeFest 2026","url":"https://www.apefest.com/","publisher":"Bored Ape Yacht Club / Yuga Labs","source_date":"2026-07-27","source_date_kind":"observed","last_verified_at":"2026-07-29","evidence_scope":"current_state","stale_after":"2026-10-29","stale":false,"access_state":"accessible","access_checked_at":"2026-07-29","access_http_status":200,"access_final_url":"https://www.apefest.com/","access_note":"HTTP 200; content reachable (claim support not re-verified)"},{"id":"bayc-activations","title":"Bored Ape 