INSERT INTO nft_source_remediation_0064 (slug, profile, sources)
VALUES ('decentraland-land', '{"citation_schema":"field-v1","evidence_policy":{"schema":"forensic-freshness-v1","status_basis":"direct_current","status_as_of":"2026-05-20","last_verified_at":"2026-07-29","next_review_at":"2026-10-29","stale":false},"launched":"LAND''s original Terraform allocation occurred in 2017; Decentraland''s public virtual world launched on 2020-02-20. These are separate lifecycle milestones.","supply":"90,601 coordinate-linked LAND parcels in Genesis City. Estates combine adjacent parcels and do not create new underlying LAND; Worlds, NAMEs, Wearables and Emotes are separate assets.","mint_price":"The 2017 protocol design specified 1,000 MANA to claim an unclaimed LAND parcel. This is not represented as the realized average for every parcel or as an aggregate LAND raise; auction/allocation outcomes and secondary prices are separate.","community_history":"LAND moved from a 2017 allocation into a publicly launched, community-built virtual world with DAO participation for LAND, MANA and NAME holders. Current documentation supports buying, renting, building, governance and events but not active-owner retention.","founder_engagement":"The original whitepaper is attributed to Esteban Ordano, Ariel Meilich, Yemel Jardi and Manuel Araoz. Current responsibilities are divided between the Decentraland Foundation and DAO, with the Foundation''s role planned to phase toward DAO control by 2030.","benefits":"LAND owners can control and publish scenes on coordinate-linked parcels, combine parcels into Estates, rent or transfer them, and receive governance voting power. Benefits depend on current protocol and DAO rules; no yield or appreciation guarantee is asserted.","business":"LAND anchors creator publishing, rentals and marketplace exchange in MANA. Current protocol documentation says creators retain 97.5% of earnings and 2.5% is reinvested through the DAO, but this is ecosystem-wide and not a LAND-owner revenue guarantee.","analysis":"Middling means the world, LAND tooling, marketplace and governance are operational, while current primary evidence does not establish strong LAND demand or owner activity. A 2026 Estate fingerprint vulnerability was patched with no observed exploitation, demonstrating both continuing maintenance and smart-contract risk. No floor, volume, holders, rentals, occupancy, revenue or return claim is made.","team":{"original_whitepaper_authors":["Esteban Ordano","Ariel Meilich","Yemel Jardi","Manuel Araoz"],"current_stewards":["Decentraland DAO","Decentraland Foundation"],"transition":"Foundation responsibilities are planned to transition fully to the DAO by 2030.","source_ids":["dcl-whitepapers","dcl-about"]},"chronology":[{"date":"2017","event":"Original whitepaper and Terraform LAND allocation established coordinate-linked NFT land.","source_ids":["dcl-whitepaper","dcl-whitepapers"]},{"date":"2020-02-20","event":"Decentraland publicly launched and established the DAO and Foundation model.","source_ids":["dcl-whitepaper2"]},{"date":"2024","event":"Whitepaper 2.0 documented 90,601 Genesis City parcels and the long-term DAO transition.","source_ids":["dcl-whitepaper2"]},{"date":"2026-05-20","event":"Estate fingerprint vulnerability patched; first-party integrations updated and no exploitation observed.","source_ids":["dcl-security-2026"]}],"market_holder_boundaries":{"market":"No current LAND floor, volume, bid depth, rental income, occupancy, liquidity or realized return.","holders":"No unique LAND-owner, concentration, active-builder or retention series.","available_evidence":"Marketplace and tooling operation prove functionality; operator download or ecosystem metrics are not LAND market measures.","source_ids":["dcl-marketplace-current","dcl-overview","dcl-security-2026"]},"products_and_value_capture":{"products":["coordinate-linked LAND","Estates","scene publishing","marketplace purchase/sale/rental","DAO voting power","Genesis City experiences"],"capture":"Creators may monetize content and rentals, while marketplace/DAO economics exist at ecosystem level; no standardized LAND cash flow is promised.","source_ids":["dcl-whitepaper","dcl-marketplace-current","dcl-about"]},"why":{"finding":"LAND supplies persistent location, adjacency, publishing control and governance in a traversable world. That provides functional differentiation, but current evidence does not show whether scarce location translates into durable financial demand.","source_ids":["dcl-whitepaper","dcl-overview","dcl-about"]},"strategic_choices":[{"choice":"Map each NFT one-to-one to coordinates in a contiguous Genesis City.","source_ids":["dcl-whitepaper","dcl-whitepaper2"]},{"choice":"Use MANA for initial LAND claims and marketplace exchange while enabling owner-controlled content.","source_ids":["dcl-whitepaper"]},{"choice":"Split stewardship between Foundation and DAO, with a planned transition to DAO control by 2030.","source_ids":["dcl-about","dcl-whitepaper2"]}],"counterfactual":{"finding":"Without usable publishing, marketplace and governance infrastructure, LAND would retain tokenized coordinates but lose much of its functional reason to hold. Current maintenance avoids that outcome, while demand and profitability remain unproven.","source_ids":["dcl-overview","dcl-marketplace-current","dcl-security-2026"]},"risks":[{"risk":"The 2026 Estate fingerprint incident shows upgrade and marketplace-order risk even when no exploitation is observed.","source_ids":["dcl-security-2026"]},{"risk":"LAND scarcity does not ensure active content, visitors, rental demand or liquidity.","source_ids":["dcl-whitepaper2","dcl-overview"]},{"risk":"DAO/Foundation transition may change operational responsibility and execution capacity.","source_ids":["dcl-about","dcl-whitepaper2"]}],"unknowns":["Aggregate LAND allocation proceeds and realized average initial price.","Current unique owners, concentration, active scenes, rental occupancy and owner retention.","Current floor, volume, liquidity, rental revenue and creator earnings attributable specifically to LAND.","Long-term operational details of the Foundation-to-DAO transition."],"review":{"last_verified_at":"2026-07-29","next_review_at":"2026-10-29","triggers":["fingerprint migration cutoff","LAND contract upgrade","marketplace or client shutdown","DAO/Foundation responsibility change"]},"evidence":[{"field":"launch","value":"2017 LAND allocation; public world launch 2020-02-20","as_of":"2020-02-20","basis":"operator","source_ids":["dcl-whitepapers","dcl-whitepaper2"]},{"field":"supply_or_mint","value":"90,601 Genesis City parcels; Estates and other asset classes excluded","as_of":"2024-10-01","basis":"operator","source_ids":["dcl-whitepaper2"]},{"field":"mint_price","value":"Protocol specified 1,000 MANA per unclaimed LAND; realized aggregate proceeds withheld","as_of":"2017-06-30","basis":"operator","source_ids":["dcl-whitepaper"]},{"field":"lifecycle_status","value":"middling — current operation and maintenance verified, strong market or usage demand not established","as_of":"2026-05-20","basis":"analyst","source_ids":["dcl-security-2026","dcl-marketplace-current","dcl-overview"]},{"field":"community_history","value":"Community-built world and DAO participation documented; active-owner retention withheld","as_of":"2026-05-20","basis":"operator","source_ids":["dcl-about","dcl-overview"]},{"field":"founder_engagement","value":"Four original authors identified; current Foundation/DAO stewardship and 2030 transition documented","as_of":"2026-05-20","basis":"operator","source_ids":["dcl-whitepapers","dcl-about"]},{"field":"benefits","value":"Publishing, transfer, rental, marketplace and governance functions without promised yield","as_of":"2026-05-20","basis":"operator","source_ids":["dcl-marketplace-current","dcl-overview","dcl-about"]},{"field":"business","value":"Creator, rental and marketplace ecosystem; standardized LAND revenue and owner cash flow withheld","as_of":"2026-05-20","basis":"operator","source_ids":["dcl-about","dcl-marketplace-current"]},{"field":"analysis","value":"Operation and security response verified; market, holder, occupancy and financial conclusions withheld","as_of":"2026-05-20","basis":"analyst","source_ids":["dcl-security-2026","dcl-overview"]}],"forensic_analysis":{"version":"forensic-analysis-v1","outcome":{"label":"middling","summary":"Decentraland LAND is middling: the world, LAND and Estate tooling, governance, and security maintenance remain operational, but current primary evidence does not establish strong parcel demand, owner activity, occupancy, rentals, or returns. A patched 2026 Estate vulnerability shows active stewardship and continuing smart-contract risk.","confidence":"high","as_of":"2026-05-20","source_refs":["dcl-about","dcl-overview","dcl-security-2026"]},"why":{"summary":"Decentraland made coordinate-linked land the scarce control layer for a user-built world, tied exchange and governance to MANA and DAO processes, and allowed owners to publish, combine, rent, or transfer parcels. Those mechanisms still operate, but ownership supply and tooling alone do not create compelling reasons for recurring visits or tenant demand. The observed system is maintained; the middling assessment is an inference from the absence of verified strong usage or land economics, not proof of failure.","confidence":"medium","source_refs":["dcl-whitepaper","dcl-whitepaper2","dcl-about","dcl-overview","dcl-security-2026"]},"strategic_choices":[{"confidence":"high","decision":"Use a finite coordinate grid of 90,601 Genesis City parcels as the world-control layer.","consequence":"Owners receive legible spatial control and scarcity, while productive value depends on location, content, users, and platform demand rather than scarcity alone.","source_refs":["dcl-whitepaper2","dcl-overview"]},{"confidence":"high","decision":"Price initial unclaimed LAND in MANA and connect ownership to DAO governance.","consequence":"Land and governance became linked to a native token economy, adding coordination and treasury tools as well as MANA volatility and governance-participation risk.","source_refs":["dcl-whitepaper","dcl-about"]},{"confidence":"high","decision":"Enable owner publishing, parcel aggregation into Estates, rentals, and transfers.","consequence":"LAND can function as a productive creator or tenant input, but the reviewed sources do not establish occupancy, rent, or owner revenue.","source_refs":["dcl-overview","dcl-about"]},{"confidence":"high","decision":"Maintain Estate contracts and publish a 2026 vulnerability post-mortem.","consequence":"The response demonstrates ongoing security stewardship while confirming that LAND utility depends on upgrade, indexing, and contract correctness.","source_refs":["dcl-security-2026"]}],"counterfactual":{"summary":"A world with abundant or non-tokenized publishing space could reduce acquisition friction and invite more creators, but weaken LAND scarcity and owner control. Stronger centralized curation could improve discovery and safety while reducing the open governance proposition. Neither alternative ensures repeat users.","confidence":"medium","source_refs":["dcl-whitepaper2","dcl-about","dcl-overview"]},"watch":[{"signal":"Unique visitors, repeat sessions, scene publishing, and parcel occupancy.","implication":"Growth would support productive LAND demand; flat or declining use would weaken the ownership thesis.","source_refs":["dcl-about","dcl-overview"]},{"signal":"Rental activity, creator earnings, and LAND-owner revenue distributions.","implication":"Measured cash flow would clarify value capture; absent activity would leave scarcity disconnected from use.","source_refs":["dcl-about","dcl-overview"]},{"signal":"Security incidents and Estate or LAND contract changes.","implication":"Transparent remediation supports trust; exploitation or incompatible upgrades could impair ownership and utility.","source_refs":["dcl-security-2026"]}],"unknowns":["How many unique owners actively publish, rent, or manage LAND?","What are current visitor retention, scene engagement, and parcel occupancy?","What rental, marketplace, creator, and DAO economics accrue specifically to LAND owners?","How concentrated are LAND and governance power, and how exposed are Estates to unresolved contract risk?"],"review":{"status":"current","last_reviewed_at":"2026-07-29","next_review_at":"2026-10-29","reviewer":"chaindump-research-desk"}}}', '[{"id":"dcl-whitepaper","title":"Decentraland Original Whitepaper","url":"https://decentraland.org/whitepaper.pdf","publisher":"Decentraland","source_date":"2017-06-30","source_date_kind":"published","last_verified_at":"2026-07-29","evidence_scope":"historical_event","stale_after":null,"stale":false,"access_state":"accessible","access_checked_at":"2026-07-29","access_http_status":200,"access_final_url":"https://decentraland.org/whitepaper.pdf","access_note":"HTTP 200; content reachable (claim support not re-verified)"},{"id":"dcl-whitepapers","title":"Decentraland Docs — Whitepapers and original authors","url":"https://docs.decentraland.org/introduction/whitepaper","publisher":"Decentraland","source_date":"2026-04-29","source_date_kind":"updated","last_verified_at":"2026-07-29","evidence_scope":"mechanism","stale_after":null,"stale":false,"access_state":"accessible","access_checked_at":"2026-07-29","access_http_status":200,"access_final_url":"https://docs.decentraland.org/introduction/whitepaper","access_note":"HTTP 200; content reachable (claim support not re-verified)"},{"id":"dcl-whitepaper2","title":"Decentraland Whitepaper 2.0","url":"https://decentraland.org/whitepaper2.pdf","publisher":"Decentraland","source_date":"2024-10-01","source_date_kind":"published","last_verified_at":"2026-07-29","evidence_scope":"mechanism","stale_after":null,"stale":false,"access_state":"accessible","access_checked_at":"2026-07-29","access_http_status":200,"access_final_url":"https://decentraland.org/whitepaper2.pdf","access_note":"HTTP 200; content reachable (claim support not re-verified)"},{"id":"dcl-about","title":"About Decentraland","url":"https://docs.decentraland.org/introduction/about-decentraland","publisher":"Decentraland","source_date":"2026-02-28","source_date_kind":"updated","last_verified_at":"2026-07-29","evidence_scope":"current_state","stale_after":"2026-10-29","stale":false,"access_state":"accessible","access_checked_at":"2026-07-29","access_http_status":200,"access_final_url":"https://docs.decentraland.org/introduction/about-decentraland","access_note":"HTTP 200; content reachable (claim support not re-verified)"},{"id":"dcl-overview","title":"Genesis City versus Worlds — Decentraland Docs","url":"https://docs.decentraland.org/in-world/overview","publisher":"Decentraland","source_date":"2026-03-31","source_date_kind":"updated","last_verified_at":"2026-07-29","evidence_scope":"current_state","stale_after":"2026-10-29","stale":false,"access_state":"accessible","access_checked_at":"2026-07-29","access_http_status":200,"access_final_url":"https://docs.decentraland.org/in-world/overview","access_note":"HTTP 200; content reachable (claim support not re-verified)"},{"id":"dcl-marketplace","title":"Decentraland Marketplace Documentation","url":"https://docs.decentraland.org/docs/land-manager","publisher":"Decentraland","source_date":"2025-07-29","source_date_kind":"updated","last_verified_at":"2026-07-29","evidence_scope":"current_state","stale_after":"2026-10-29","stale":false,"access_state":"dead","access_checked_at":"2026-07-29","access_http_status":404,"access_final_url":"https://docs.decentraland.org/docs/land-manager","access_note":"HTTP 404 — Decentraland Docs"},{"id":"dcl-security-2026","title":"May 2026 Estate Fingerprint Collision Vulnerability Post-Mortem","url":"https://forum.decentraland.org/t/may-2026-estate-fingerprint-collision-vulnerability-post-mortem/25272","publisher":"Decentraland Foundation / Decentraland Forum","source_date":"2026-05-20","source_date_kind":"event","last_verified_at":"2026-07-29","evidence_scope":"current_state","stale_after":"2026-10-29","stale":false,"access_state":"accessible","access_checked_at":"2026-07-29","access_http_status":200,"access_final_url":"https://forum.decentraland.org/t/may-2026-estate-fingerprint-collision-vulnerability-post-mortem/25272","access_note":"HTTP 200; content reachable (claim support not re-verified)"},{"id":"dcl-marketplace-current","title":"LAND Manager","url":"https://docs.decentraland.org/marketplace/land-manager","publisher":"Decentraland","source_date":"2026-07-29","source_date_kind":"observed","evidence_scope":"current_state","source_tier":"B","source_role":"primary","independence_group":"decentraland_operator","resolving":true,"evidence_reviewed":true,"evidence_reviewer":"codex-research-agent","evidence_reviewed_at":"2026-07-29","stale_after":"2026-10-29","stale":false,"access_state":"accessible","access_checked_at":"2026-07-29","checked_at":"2026-07-29","last_verified_at":"2026-07-29","access_http_status":200,"verification_note":"HTTP 200; current official LAND and Estate management documentation inspected."}]');

