INSERT INTO nft_source_remediation_0064 (slug, profile, sources)
VALUES ('f1-delta-time', NULL, '[{"id":"f1dt-closure","title":"F1 Delta Time to cease operations; rewards announced for supporters","url":"https://www.animocabrands.com/f1-delta-time-to-cease-operations-announces-rewards-for-supporters","publisher":"Animoca Brands","source_date":"2022-03-16","source_date_kind":"event","checked_at":"2026-07-29","last_verified_at":"2026-07-29","evidence_scope":"terminal_outcome","stale_after":null,"stale":false,"source_tier":"T2","source_role":"primary","access_state":"accessible","resolving":true,"evidence_reviewed":false,"verification_note":"Operator notice confirms cessation, inability to renew the Formula 1 licence, and the available replacement or payout paths. It does not disclose licence negotiations, economics, player counts, or completion rates.","access_checked_at":"2026-07-29","access_http_status":200,"access_final_url":"https://www.animocabrands.com/announcement/f1-delta-time-to-cease-operations-announces-rewards-for-supporters","access_note":"HTTP 200; content reachable (claim support not re-verified)"},{"id":"f1dt-racefans","title":"Official Formula 1 NFT game F1 Delta Time closes three years after launch","url":"https://www.racefans.net/2022/04/01/official-formula-1-nft-game-f1-delta-time-closes-three-years-after-launch/","publisher":"RaceFans","source_date":"2022-04-01","source_date_kind":"published","checked_at":"2026-07-29","last_verified_at":"2026-07-29","evidence_scope":"terminal_outcome","stale_after":null,"stale":false,"source_tier":"T3","source_role":"independent","access_state":"resolving","resolving":true,"evidence_reviewed":false,"verification_note":"Independent motorsport reporting confirms launch timing, closure after non-renewal of the Formula 1 licence, and historically high-value NFT sales. Sale values are historical transactions, not current valuation or holder recovery."}]');

INSERT INTO nft_source_remediation_0064 (slug, profile, sources)
VALUES ('funko-digital-pop', '{"citation_schema":"field-v1","evidence_policy":{"schema":"forensic-freshness-v1","status_basis":"terminal_event","status_as_of":"2026-05-31","last_verified_at":"2026-07-29","next_review_at":"2027-01-29","stale":false},"launched":"2021","founder_engagement":"Funko stopped releasing new Digital Pop! collections and disabled Droppp accounts and wallets on May 31, 2026; it committed to fulfilling outstanding physical redemption orders.","benefits":"Before shutdown, eligible digital collectibles or completed Royalty Sets could generate time-limited redemption tokens for physical Funko figures.","analysis":"Classified dead at the program layer because primary releases and the operator wallet/platform ended. Exported WAX assets can persist elsewhere, which demonstrates that token persistence is not equivalent to platform continuity.","evidence":[{"field":"launch","value":"2021 — Funko''s closure notice identifies 2021 as the Digital Pop! launch year","as_of":"2026-04-30","basis":"operator","source_ids":["funko-sunset"]},{"field":"supply_or_mint","value":"Periodically released licensed collections with pack- and rarity-specific editions; no single program-wide cap","as_of":"2026-05-31","basis":"operator","source_ids":["funko-digital-current"]},{"field":"lifecycle_status","value":"dead — no new Digital Pop! collections and Droppp accounts/wallets disabled May 31, 2026","as_of":"2026-05-31","basis":"operator","source_ids":["funko-sunset"]},{"field":"failure_signal","value":"Operator sunset the program, wallet, marketplace access, pack opening, and community Discord","as_of":"2026-05-31","basis":"operator","source_ids":["funko-sunset"]},{"field":"founder_engagement","value":"Funko stopped new releases and disabled Droppp while committing to fulfill outstanding physical redemptions","as_of":"2026-05-31","basis":"operator","source_ids":["funko-sunset"]},{"field":"benefits","value":"Eligible Digital Pop! items and Royalty Sets could receive redemption tokens exchangeable for limited physical Funko figures","as_of":"2026-05-31","basis":"operator","source_ids":["funko-digital-current"]},{"field":"analysis","value":"Dead classification applies to the operator program; exported WAX assets may persist after the primary platform and redemption system end","as_of":"2026-05-31","basis":"analyst","source_ids":["funko-sunset","funko-digital-current"]}],"forensic_analysis":{"version":"forensic-analysis-v1","outcome":{"label":"dead","summary":"Funko Digital Pop is dead at the operator-program layer: Funko stopped new releases and disabled Droppp accounts, wallets, marketplace access, pack opening, and community infrastructure on May 31, 2026. Exported WAX assets can persist, but the primary product and redemption system ended.","confidence":"high","as_of":"2026-05-31","source_refs":["funko-sunset"]},"why":{"summary":"The program connected licensed digital drops to Funko-operated custody, marketplace, pack opening, and time-limited physical redemption. That integration differentiated the product, but concentrated utility in operator services and fulfilment rather than the WAX token alone. Funko’s shutdown is observed; the causal inference is that centralized program dependence made the tokens unable to preserve their full use when the operator exited, while the business reason for exit is undisclosed.","confidence":"medium","source_refs":["funko-sunset","funko-digital-current"]},"strategic_choices":[{"confidence":"high","decision":"Release recurring licensed Digital Pop collections instead of one fixed collection.","consequence":"Periodic drops created repeat inventory and brand partnerships, while exposing the program to ongoing licensing, demand, and fulfilment requirements.","source_refs":["funko-sunset","funko-digital-current"]},{"confidence":"high","decision":"Tie selected digital items and completed sets to physical redemption tokens.","consequence":"Physical figures created differentiated utility, but value depended on eligibility windows, logistics, and Funko fulfillment rather than token ownership alone.","source_refs":["funko-digital-current"]},{"confidence":"high","decision":"Concentrate wallet, marketplace, pack-opening, and community functions in Droppp.","consequence":"The integrated experience simplified participation but created an operator shutdown point that removed most program utility at once.","source_refs":["funko-sunset"]},{"confidence":"medium","decision":"Permit WAX transfers and commit to outstanding physical redemptions during sunset.","consequence":"Export and fulfillment mitigate some losses while leaving holders without new drops or the original platform experience.","source_refs":["funko-sunset","funko-digital-current"]}],"counterfactual":{"summary":"A self-custody-first architecture with open pack and redemption standards could preserve more functionality after operator exit, but licensed physical fulfilment would still require accountable counterparties. Ending new drops while keeping read-only wallet and redemption infrastructure longer could reduce transition risk at continued operating cost.","confidence":"medium","source_refs":["funko-sunset","funko-digital-current"]},"watch":[{"signal":"Fulfillment of outstanding physical redemption obligations.","implication":"Completion affects holder recovery and trust but does not restore the sunset program.","source_refs":["funko-sunset","funko-digital-current"]},{"signal":"Continued third-party WAX transfer and display support.","implication":"External support preserves artifact access while demonstrating the boundary between token persistence and product continuity.","source_refs":["funko-digital-current"]},{"signal":"Any successor Funko digital-collectible program.","implication":"A verified replacement could change the company-level strategy, not the terminal status of Digital Pop and Droppp.","source_refs":["funko-sunset"]}],"unknowns":["Why did Funko decide to close the program and what were its revenue and operating costs?","How many users and assets were exported before Droppp access ended?","How many physical redemptions remain outstanding and what is their fulfillment status?","What functions remain usable for WAX assets without Droppp metadata and interfaces?"],"review":{"status":"current","last_reviewed_at":"2026-07-29","next_review_at":"2027-01-29","reviewer":"chaindump-research-desk"}}}', '[{"id":"funko-sunset","title":"Funko — Digital Pop! update: Droppp program sunsets May 31, 2026","url":"https://funko.com/funko-blog-home/funko-digital-pop-update.html","publisher":"Funko","source_date":"2026-05-31","source_date_kind":"event","last_verified_at":"2026-07-29","evidence_scope":"terminal_outcome","stale_after":null,"stale":false,"checked_at":"2026-07-29","access_state":"accessible","access_checked_at":"2026-07-29","access_http_status":200,"access_final_url":"https://funko.com/funko-blog-home/funko-digital-pop-update.html","access_note":"HTTP 200; content reachable (claim support not re-verified)"},{"id":"funko-faq","title":"Funko Digital Pop! FAQ — WAX transfers, packs, and physical redemption","url":"https://digital.funko.com/faq","publisher":"Funko","source_date":null,"source_date_kind":"unknown","last_verified_at":"2026-07-29","evidence_scope":"mechanism","stale_after":null,"stale":false,"checked_at":"2026-07-29","access_state":"unverified","access_checked_at":"2026-07-29","access_http_status":503,"access_final_url":"https://digital.funko.com/faq","access_note":"HTTP 503"},{"id":"funko-digital-current","title":"Funko Digital Pop — program mechanics and sunset notice","url":"https://funko.com/digital-pop.html","publisher":"Funko","source_date":"2026-07-29","source_date_kind":"observed","evidence_scope":"mechanism","source_tier":"B","source_role":"primary","independence_group":"funko_operator","resolving":true,"evidence_reviewed":true,"evidence_reviewer":"codex-research-agent","evidence_reviewed_at":"2026-07-29","access_state":"accessible","access_checked_at":"2026-07-29","checked_at":"2026-07-29","last_verified_at":"2026-07-29","access_http_status":200,"verification_note":"HTTP 200; current official page describes packs, redemption tokens, physical figures, marketplace use, and the sunset.","stale":false}]');

