INSERT INTO nft_source_remediation_0064 (slug, profile, sources)
VALUES ('nifty-gateway', '{"citation_schema":"field-v1","evidence_policy":{"schema":"forensic-freshness-v1","status_basis":"terminal_event","status_as_of":"2026-02-23","last_verified_at":"2026-07-29","next_review_at":"2027-02-23","stale":false},"launched":"Nifty Gateway launched in 2020 after Gemini acquired the pre-launch company in November 2019. Acquisition and product launch are separate lifecycle milestones.","supply":"Not applicable: Nifty Gateway was a custodial marketplace and digital-production platform spanning many creators and drops, not one NFT collection. Listed inventory, drops and users must not be represented as token supply or holder count.","mint_price":"Not applicable as a platform-wide mint. Individual drops used different prices and sale formats; the reviewed primary sources do not provide an audited platform-wide average mint price or aggregate creator proceeds.","community_history":"The platform combined curated drops, fiat payments, custodial wallets and a secondary marketplace. Gemini placed it in withdrawal-only mode on January 23, 2026 and closed the platform on February 23, 2026.","founder_engagement":"Gemini identifies twin brothers Duncan and Griffin as the founders and acquired Nifty Gateway in 2019. Gemini later operated the platform and made the closure decision; no standalone post-closure operating team is asserted.","benefits":"Before closure, users could access curated creator drops, fiat payment methods, custodial wallets and secondary listings. Those platform services ended; withdrawal and tax-support documentation does not make the marketplace operational.","business":"Nifty Gateway operated curated primary drops, production services and secondary transactions. Gemini said closure would concentrate resources on a one-stop super app and later reported that it had wound down Nifty Gateway; collection-level revenue, losses and creator payouts are not disclosed here.","analysis":"Dead is anchored to Gemini''s explicit February 23, 2026 closure and March 2026 public-company confirmation that Nifty Gateway was wound down. This is a platform terminal outcome, not a claim that underlying NFTs ceased to exist or that every creator project failed.","team":{"founders_as_identified_by_gemini":["Duncan","Griffin"],"owner_operator":"Gemini","post_closure_boundary":"Gemini Wallet may support NFTs, but it is not continuation of the Nifty Gateway marketplace.","source_ids":["nifty-acquisition","nifty-closure","nifty-winddown-sec"]},"chronology":[{"date":"2019-11-19","event":"Gemini acquired the pre-launch Nifty Gateway company.","source_ids":["nifty-acquisition"]},{"date":"2020","event":"Nifty Gateway launched as an NFT platform.","source_ids":["nifty-closure"]},{"date":"2026-01-23","event":"Gemini put the platform into withdrawal-only mode and announced a February 23 closure.","source_ids":["nifty-closure"]},{"date":"2026-02-23","event":"Nifty Gateway closed; Gemini''s March 2026 filing subsequently confirmed it had been wound down.","source_ids":["nifty-closure","nifty-winddown-sec"]}],"market_holder_boundaries":{"market":"No current marketplace floor, volume, bid depth or liquidity because the platform closed.","holders":"Not a collection: users, custodial accounts, creators and owners of underlying NFTs are different populations, and no current count is asserted.","available_evidence":"Operator closure and public-company wind-down confirmation establish terminal platform status, not the status or value of underlying assets.","source_ids":["nifty-closure","nifty-winddown-sec"]},"products_and_value_capture":{"products":["curated primary drops","digital-production studio","fiat payment methods","custodial wallets","secondary marketplace"],"capture":"Historical platform economics existed across drops and trades, but audited Nifty-specific revenue, loss, fees and creator payouts are withheld.","source_ids":["nifty-s1-sec","nifty-closure"]},"why":{"finding":"Gemini explicitly framed closure as resource concentration around its one-stop super app. A prior filing documented commercial-viability risk, but this dossier does not promote that general risk into an unsupported sole cause.","source_ids":["nifty-closure","nifty-risk-sec","nifty-winddown-sec"]},"strategic_choices":[{"choice":"Use Gemini ownership, fiat payments and custodial wallets to reduce purchase friction.","source_ids":["nifty-acquisition","nifty-s1-sec"]},{"choice":"Pair curated drops with production services and a secondary marketplace.","source_ids":["nifty-s1-sec"]},{"choice":"Enter withdrawal-only mode before closure and redirect NFT support toward Gemini Wallet.","source_ids":["nifty-closure"]}],"counterfactual":{"finding":"A sale or independent operating model might have preserved the marketplace, but the reviewed primary sources do not say one was pursued. Gemini instead chose wind-down and product concentration.","source_ids":["nifty-closure","nifty-winddown-sec"]},"risks":[{"risk":"Custodial users faced withdrawal and self-custody work before shutdown.","source_ids":["nifty-closure"]},{"risk":"Platform closure can strand interfaces and community coordination even when underlying blockchain assets persist.","source_ids":["nifty-closure","nifty-help"]},{"risk":"Gemini had disclosed that weak NFT demand or volume could make the business commercially nonviable, but exact closure economics remain undisclosed.","source_ids":["nifty-risk-sec"]}],"unknowns":["Nifty Gateway-specific revenue, losses and closure costs.","Number and value of assets withdrawn, migrated or left unresolved at closure.","Creator payout and support obligations remaining after shutdown.","Whether any Nifty technology, staff or IP continues inside Gemini products."],"review":{"last_verified_at":"2026-07-29","next_review_at":"2027-02-23","triggers":["new Gemini filing","support-center shutdown","asset-recovery update","sale or relaunch announcement"]},"evidence":[{"field":"launch","value":"2020 platform launch after Gemini''s 2019 acquisition","as_of":"2020-12-31","basis":"operator","source_ids":["nifty-acquisition","nifty-closure"]},{"field":"supply_or_mint","value":"Not applicable to a multi-creator marketplace platform","as_of":"2026-02-23","basis":"operator","source_ids":["nifty-s1-sec","nifty-closure"]},{"field":"mint_price","value":"Not applicable platform-wide; drop formats varied and aggregate proceeds withheld","as_of":"2026-02-23","basis":"operator","source_ids":["nifty-s1-sec"]},{"field":"lifecycle_status","value":"dead — platform closed 2026-02-23 and Gemini subsequently confirmed wind-down","as_of":"2026-02-23","basis":"operator","source_ids":["nifty-closure","nifty-winddown-sec"]},{"field":"community_history","value":"Curated platform entered withdrawal-only mode and then closed; underlying NFTs are outside terminal claim","as_of":"2026-02-23","basis":"operator","source_ids":["nifty-closure"]},{"field":"founder_engagement","value":"Founders and Gemini acquisition documented; Gemini made the closure decision","as_of":"2026-02-23","basis":"operator","source_ids":["nifty-acquisition","nifty-closure"]},{"field":"benefits","value":"Historical drops, fiat, custody and secondary market ended with closure","as_of":"2026-02-23","basis":"operator","source_ids":["nifty-s1-sec","nifty-closure"]},{"field":"business","value":"Resource-concentration rationale and wind-down verified; exact economics withheld","as_of":"2026-03-19","basis":"operator","source_ids":["nifty-closure","nifty-winddown-sec"]},{"field":"analysis","value":"Terminal marketplace outcome verified; underlying asset and creator outcomes bounded separately","as_of":"2026-02-23","basis":"analyst","source_ids":["nifty-closure","nifty-winddown-sec"]}],"token_model":{"finding":"No Nifty Gateway fungible token or continuing platform revenue right is established. The model captured value through curated drops, production services, and secondary trading within Gemini-linked fiat and custody rails.","boundary":"Gemini Wallet support after closure preserves asset access; it does not continue the Nifty marketplace business.","source_ids":["nifty-acquisition","nifty-s1-sec","nifty-closure"]},"chain_dependence":{"finding":"Ethereum-based NFT ownership could move beyond the platform, but Nifty''s differentiators—fiat checkout, custody, curation, studio services, and marketplace distribution—depended on Gemini-operated infrastructure.","source_ids":["nifty-acquisition","nifty-s1-sec","nifty-closure"]},"forensic_analysis":{"version":"forensic-analysis-v1","outcome":{"label":"dead","scope":"Nifty Gateway marketplace and studio operations; externally held NFTs and Gemini Wallet are excluded","summary":"Gemini moved Nifty Gateway to withdrawal-only mode and completed the marketplace wind-down while redirecting asset support to Gemini Wallet.","confidence":"high","as_of":"2026-02-23","source_refs":["nifty-closure","nifty-winddown-sec"]},"why":{"summary":"Observed: Gemini said it closed Nifty Gateway to concentrate resources on a one-stop super app, after public filings had already identified commercial-viability risk in the NFT business. Inference: a curated marketplace became non-core inside a broader exchange strategy; the evidence does not prove weak demand or losses were the sole cause.","basis":"company closure statement and SEC filings; sole-cause attribution withheld","confidence":"high","source_refs":["nifty-risk-sec","nifty-closure","nifty-winddown-sec"]},"strategic_choices":[{"decision":"Use Gemini ownership, fiat payments, and custodial wallets to reduce NFT purchase friction.","intended_mechanism":"Reach collectors who did not want to manage crypto wallets directly.","consequence":"Nifty differentiated on access, while becoming strategically and operationally dependent on Gemini.","confidence":"high","source_refs":["nifty-acquisition","nifty-s1-sec"]},{"decision":"Pair curated drops with studio production and a secondary marketplace.","intended_mechanism":"Control creator onboarding, launch quality, and ongoing trading in one venue.","consequence":"The full-service model created a recognizable platform but also required continuing curation, production, custody, and marketplace operations.","confidence":"high","source_refs":["nifty-s1-sec"]},{"decision":"Wind down rather than maintain or separate the marketplace.","intended_mechanism":"Concentrate Gemini resources on its super-app strategy.","consequence":"Marketplace and studio operations ended; withdrawal support reduced custody harm but did not preserve the business.","confidence":"high","source_refs":["nifty-closure","nifty-winddown-sec"]}],"counterfactual":{"summary":"An independent sale, spinout, or lower-cost creator platform might have preserved Nifty''s brand and marketplace, but the reviewed sources do not show that Gemini pursued one or that it would have been commercially viable.","limits":"No platform-level revenue, cost, bid-depth, buyer-retention, or sale-process data are disclosed.","confidence":"low","source_refs":["nifty-risk-sec","nifty-closure","nifty-winddown-sec"]},"watch":[{"signal":"Completion of remaining withdrawals and continued Gemini Wallet support for former Nifty assets.","implication":"Orderly asset access limits customer harm but does not change the terminal marketplace classification.","source_refs":["nifty-closure"]},{"signal":"A disclosed acquisition or relaunch of the Nifty Gateway brand, creator tooling, or marketplace.","implication":"A functioning successor could justify a recovery case scoped to that new operator.","source_refs":["nifty-closure","nifty-winddown-sec"]}],"unknowns":["What were Nifty Gateway''s final revenue, costs, active buyers, and trading liquidity?","Did Gemini solicit a sale, spinout, or licensing transaction before closure?","Were all custodial assets withdrawn or migrated successfully?","What continuing rights or obligations remain for artists whose drops were produced by Nifty Gateway?"],"review":{"status":"current","last_reviewed_at":"2026-07-29","next_review_at":"2027-02-23","reviewer":"chaindump-research-desk"}}}', '[{"id":"nifty-acquisition","title":"Gemini Expands Into NFTs With Nifty Gateway","url":"https://www.gemini.com/blog/gemini-expands-into-non-fungible-tokens-nfts-with-nifty-gateway-tm","publisher":"Gemini","source_date":"2019-11-19","source_date_kind":"published","last_verified_at":"2026-07-29","evidence_scope":"historical_event","stale_after":null,"stale":false,"checked_at":"2026-07-29","access_state":"accessible","access_checked_at":"2026-07-29","access_http_status":200,"access_final_url":"https://www.gemini.com/blog/gemini-expands-into-non-fungible-tokens-nfts-with-nifty-gateway-tm","access_note":"HTTP 200; content reachable (claim support not re-verified)"},{"id":"nifty-s1","title":"Gemini Space Station S-1 — Nifty Gateway Studio description","url":"https://investors.gemini.com/static-files/387885d9-75c0-4524-95b4-d550890aad3e","publisher":"Gemini Space Station, Inc.","source_date":"2025-09-02","source_date_kind":"published","last_verified_at":"2026-07-29","evidence_scope":"mechanism","stale_after":null,"stale":false,"checked_at":"2026-07-29","access_state":"unverified","access_checked_at":"2026-07-29","access_http_status":null,"access_final_url":null,"access_note":"timeout after 15s"},{"id":"nifty-risk","title":"Gemini Q3 2025 Form 10-Q — NFT business risk","url":"https://investors.gemini.com/static-files/0385bebc-c005-47c3-9704-a71ef00ec224","publisher":"Gemini Space Station, Inc.","source_date":"2025-11-10","source_date_kind":"published","last_verified_at":"2026-07-29","evidence_scope":"mechanism","stale_after":null,"stale":false,"checked_at":"2026-07-29","access_state":"unverified","access_checked_at":"2026-07-29","access_http_status":null,"access_final_url":null,"access_note":"timeout after 15s"},{"id":"nifty-closure","title":"Announcing Nifty Gateway''s Closure","url":"https://www.gemini.com/es/blog/announcing-nifty-gateways-closure","publisher":"Gemini","source_date":"2026-01-23",