UPDATE nft_collections
SET profile = COALESCE((
      SELECT patch.profile FROM nft_source_remediation_0064 AS patch WHERE patch.slug = nft_collections.slug
    ), profile),
    sources = (
      SELECT patch.sources FROM nft_source_remediation_0064 AS patch WHERE patch.slug = nft_collections.slug
    ),
    updated_at = '2026-07-29'
WHERE slug IN (SELECT slug FROM nft_source_remediation_0064);

DROP TABLE IF EXISTS nft_source_remediation_0064;
